		case REV_DSIO:
		case REV_DENV:
			m_cpu->set_input_line(INPUT_LINE_HALT, ASSERT_LINE);
			m_dsio.start_on_next_write = 0;
			break;
	}

// if not enabled, skip
	if (!m_timer_enable)
		return;

	// compute the time until the first firing
	m_timer_start_cycles = m_cpu->total_cycles();
	m_timers_fired = 0;

