			m_program->read_dword(0x30) == 0x0c0030 &&      // ENA SEC_REG
			m_program->read_dword(0x31) == 0x014828 &&      // SI = IO($0482)
			m_program->read_dword(0x32) == 0x01c828 &&      // IO($0482) = SI
