				break;

			case 2: // read data
				result = 0x5a00 | ((sdrc.seed & 0x3f) << 1);
				break;

			case 3: // shift left
				result = 0x5ab9;
				break;

			case 4: // add
				result = 0x5a03;
				break;

			case 5: // xor
				result = 0x5a69;
				break;

			case 6: // prg
				result = 0x5a20;
				break;

			case 7: // invert
				result = 0x5aff;
				break;
		}
	}

